script:
/* Fitout Project Command Centre — Custom HTML Block script.
   `root_element` is the block's shadow root (provided by Frappe). */
(function () {
  "use strict";
  const ROOT = root_element;
  const HOST = ROOT.host;
  const $ = (s) => ROOT.querySelector(s);
  const $$ = (s) => Array.from(ROOT.querySelectorAll(s));

  if (window.__foDash && typeof window.__foDash.destroy === "function") window.__foDash.destroy();

  const LS = "fo_cmd_centre_v1";
  const esc = (v) => frappe.utils.escape_html(v == null ? "" : String(v));

  /* ---------------- icons (Lucide) ---------------- */
  const P = {
    building: '<rect x="4" y="2" width="16" height="20" rx="2"/><path d="M9 22v-4h6v4"/><path d="M8 6h.01M16 6h.01M12 6h.01M12 10h.01M12 14h.01M16 10h.01M16 14h.01M8 10h.01M8 14h.01"/>',
    calclock: '<path d="M21 7.5V6a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h3.5"/><path d="M16 2v4M8 2v4M3 10h5"/><path d="M17.5 17.5 16 16.3V14"/><circle cx="16" cy="16" r="6"/>',
    filecheck: '<path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z"/><path d="M14 2v4a2 2 0 0 0 2 2h4"/><path d="m9 15 2 2 4-4"/>',
    alert: '<path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3"/><path d="M12 9v4"/><path d="M12 17h.01"/>',
    filediff: '<path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z"/><path d="M14 2v4a2 2 0 0 0 2 2h4"/><path d="M9 12h6M12 9v6M9 18h6"/>',
    filetext: '<path d="M15 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V7Z"/><path d="M14 2v4a2 2 0 0 0 2 2h4"/><path d="M16 13H8M16 17H8M10 9H8"/>',
    truck: '<path d="M14 18V6a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v11a1 1 0 0 0 1 1h2"/><path d="M15 18H9"/><path d="M19 18h2a1 1 0 0 0 1-1v-3.65a1 1 0 0 0-.22-.62l-3.48-4.35A1 1 0 0 0 17.52 8H14"/><circle cx="17" cy="18" r="2"/><circle cx="7" cy="18" r="2"/>',
    bang: '<path d="M12 6v8"/><path d="M12 18h.01"/>',
    flag: '<path d="M4 15s1-1 4-1 5 2 8 2 4-1 4-1V3s-1 1-4 1-5-2-8-2-4 1-4 1z"/><path d="M4 22v-7"/>',
    receipt: '<path d="M4 2v20l2-1 2 1 2-1 2 1 2-1 2 1 2-1 2 1V2l-2 1-2-1-2 1-2-1-2 1-2-1-2 1Z"/><path d="M8 7h8M8 11h8M8 15h5"/>',
    cart: '<circle cx="8" cy="21" r="1"/><circle cx="19" cy="21" r="1"/><path d="M2.05 2.05h2l2.66 12.42a2 2 0 0 0 2 1.58h9.78a2 2 0 0 0 1.95-1.57l1.65-7.43H5.12"/>',
    calendar: '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18M8 14h.01M12 14h.01M16 14h.01M8 18h.01M12 18h.01"/>',
    down: '<path d="m6 9 6 6 6-6"/>', arrow: '<path d="M5 12h14"/><path d="m12 5 7 7-7 7"/>',
    dots: '<circle cx="5" cy="12" r="1.6" fill="currentColor"/><circle cx="12" cy="12" r="1.6" fill="currentColor"/><circle cx="19" cy="12" r="1.6" fill="currentColor"/>',
    open: '<path d="M15 3h6v6"/><path d="M10 14 21 3"/><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>',
    list: '<path d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01"/>',
    edit: '<path d="M12 20h9"/><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z"/>',
    plus: '<path d="M5 12h14M12 5v14"/>',
    refresh: '<path d="M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8"/><path d="M21 3v5h-5"/><path d="M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16"/><path d="M8 16H3v5"/>',
    info: '<circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/>',
    back: '<path d="m12 19-7-7 7-7"/><path d="M19 12H5"/>',
    pin: '<path d="M20 10c0 4.99-5.54 10.19-7.4 11.8a1 1 0 0 1-1.2 0C9.54 20.19 4 14.99 4 10a8 8 0 0 1 16 0"/><circle cx="12" cy="10" r="3"/>',
    user: '<circle cx="12" cy="8" r="5"/><path d="M20 21a8 8 0 0 0-16 0"/>',
    camera: '<path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"/><circle cx="12" cy="13" r="3"/>',
    wrench: '<path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>',
    clock: '<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>',
    checksq: '<rect x="3" y="3" width="18" height="18" rx="2"/><path d="m9 12 2 2 4-4"/>',
    upload: '<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="m17 8-5-5-5 5"/><path d="M12 3v12"/>',
    search: '<circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/>',
    package: '<path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><path d="m3.3 7 8.7 5 8.7-5"/><path d="M12 22V12"/>',
    calc: '<rect x="4" y="2" width="16" height="20" rx="2"/><path d="M8 6h8M8 10h.01M12 10h.01M16 10h.01M8 14h.01M12 14h.01M16 14h.01M8 18h.01M12 18h.01M16 18h.01"/>',
    database: '<ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M3 5v14a9 3 0 0 0 18 0V5"/><path d="M3 12a9 3 0 0 0 18 0"/>',
    check: '<path d="M20 6 9 17l-5-5"/>',
    grid: '<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/>',
    trash: '<path d="M3 6h18M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/>',
    hardhat: '<path d="M2 18a1 1 0 0 0 1 1h18a1 1 0 0 0 1-1v-2a1 1 0 0 0-1-1H3a1 1 0 0 0-1 1v2z"/><path d="M10 10V5a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1v5"/><path d="M4 15v-3a6 6 0 0 1 6-6"/><path d="M14 6a6 6 0 0 1 6 6v3"/>',
    users: '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
    clipboard: '<rect x="8" y="2" width="8" height="4" rx="1"/><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/><path d="M12 11h4M12 16h4M8 11h.01M8 16h.01"/>',
  };
  const ic = (n, cls) => `<svg class="i ${cls || ""}" viewBox="0 0 24 24" aria-hidden="true">${P[n] || ""}</svg>`;

  /* ---------------- state ---------------- */
  const S = { company: null, scope: null, preset: "year", from: null, to: null, data: null, alive: true, seq: 0, listeners: [], modified: [], userScope: false,
    view: "dash", dataStale: false, routeStr: (frappe.get_route_str && frappe.get_route_str()) || "", basePath: window.location.pathname.replace(/\/+$/, "") };
  const on = (el, ev, fn, opt) => { el.addEventListener(ev, fn, opt); S.listeners.push([el, ev, fn, opt]); };
  const save = () => { try { localStorage.setItem(LS, JSON.stringify({ company: S.company, scope: S.userScope ? S.scope : null, preset: S.preset, from: S.from, to: S.to })); } catch (e) {} };
  const load = () => { try { return JSON.parse(localStorage.getItem(LS) || "null") || {}; } catch (e) { return {}; } };

  /* ---------------- helpers ---------------- */
  const ymd = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  const toDate = (s) => { if (!s) return null; const [y, m, d] = String(s).slice(0, 10).split("-").map(Number); return new Date(y, m - 1, d); };
  const MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const fmtD = (s) => { const d = toDate(s); return d && !isNaN(d) ? `${String(d.getDate()).padStart(2, "0")} ${MON[d.getMonth()]} ${d.getFullYear()}` : ""; };
  const fmtMoney = (v, cur) => {
    v = flt(v);
    try { return format_currency(v, cur, 0); } catch (e) { return (cur ? cur + " " : "") + Math.round(v).toLocaleString(); }
  };
  const shortName = (n) => { if (!n) return ""; const p = String(n).trim().split(/\s+/); return p.length > 1 ? `${p[0]} ${p[p.length - 1][0].toUpperCase()}.` : p[0]; };
  const hcls = (h) => "h-" + String(h || "on track").toLowerCase().replace(/\s+/g, "-");
  const STAGE_COLOR = { "Enquiry & Requirements": "#94A3B8", "Estimation & BOQ": "#8C97AE", "Contract Award": "#6366F1", "Design & Approvals": "#7C3AED",
    Procurement: "#F97316", "Site Execution": "#2563EB", "Commercial Review": "#0EA5E9", "Handover & Closure": "#059669", Completed: "#059669",
    Planning: "#8C97AE", Installation: "#2563EB", Testing: "#0EA5E9", Handover: "#059669" };
  const today = () => { const t = new Date(); t.setHours(0, 0, 0, 0); return t; };

  async function api(method, args) {
    const qs = new URLSearchParams();
    Object.keys(args || {}).forEach((k) => { if (args[k] != null && args[k] !== "") qs.set(k, args[k]); });
    const res = await fetch(`/api/method/${method}?${qs}`, { headers: { Accept: "application/json", "X-Frappe-CSRF-Token": frappe.csrf_token || "" }, credentials: "same-origin" });
    let body = {}; try { body = await res.json(); } catch (e) {}
    if (!res.ok) {
      let msg = body.exception || `HTTP ${res.status}`;
      try { if (body._server_messages) msg = JSON.parse(JSON.parse(body._server_messages)[0]).message || msg; } catch (e) {}
      throw new Error(String(msg).replace(/<[^>]+>/g, "").slice(0, 180));
    }
    return body.message;
  }
  const goForm = (dt, name) => name && frappe.set_route("Form", dt, name);
  function goList(dt, opts) { frappe.route_options = opts || {}; frappe.set_route("List", dt); }
  const projectListOpts = () => { const o = { status: "Open" }; if (S.company) o.company = S.company; if (S.scope === "fitout") o.fo_is_fitout = 1; return o; };

  /* ---------------- date range ---------------- */
  const PRESETS = [["year", "This Year"], ["last_year", "Last Year"], ["quarter", "This Quarter"], ["month", "This Month"], ["l12", "Last 12 Months"], ["next12", "Next 12 Months"]];
  function presetRange(p) {
    const t = today(), y = t.getFullYear(), m = t.getMonth();
    if (p === "last_year") return [new Date(y - 1, 0, 1), new Date(y - 1, 11, 31)];
    if (p === "quarter") { const q = Math.floor(m / 3) * 3; return [new Date(y, q, 1), new Date(y, q + 3, 0)]; }
    if (p === "month") return [new Date(y, m, 1), new Date(y, m + 1, 0)];
    if (p === "l12") return [new Date(y, m - 11, 1), new Date(y, m + 1, 0)];
    if (p === "next12") return [new Date(y, m, 1), new Date(y, m + 12, 0)];
    return [new Date(y, 0, 1), new Date(y, 11, 31)];
  }
  function setRange(p, from, to) {
    S.preset = p;
    if (p === "custom") { S.from = from; S.to = to; } else { const r = presetRange(p); S.from = ymd(r[0]); S.to = ymd(r[1]); }
    $(".fo-range-txt").textContent = `${fmtD(S.from)} - ${fmtD(S.to)}`;
    save();
  }
  function renderRangeMenu() {
    $(".fo-range-menu").innerHTML = PRESETS.map(([k, l]) => `<a data-preset="${k}" class="${S.preset === k ? "on" : ""}">${l}</a>`).join("") +
      `<hr><a data-preset="custom" class="${S.preset === "custom" ? "on" : ""}">${ic("calendar", "sm")}Custom range…</a>`;
  }
  function askCustom() {
    const d = new frappe.ui.Dialog({
      title: __("Date Range"),
      fields: [{ fieldname: "from_date", label: __("From"), fieldtype: "Date", reqd: 1, default: S.from },
               { fieldtype: "Column Break" },
               { fieldname: "to_date", label: __("To"), fieldtype: "Date", reqd: 1, default: S.to }],
      primary_action_label: __("Apply"),
      primary_action(v) { d.hide(); setRange("custom", v.from_date, v.to_date); refresh(); },
    });
    d.show();
  }

  /* ---------------- floating menu ---------------- */
  function openMenu(anchor, items) {
    const m = $(".fo-float-menu");
    m.innerHTML = items.map((it, i) => it === "-" ? "<hr>" : `<a data-mi="${i}">${ic(it.icon || "open", "sm")}${esc(it.label)}</a>`).join("");
    m.hidden = false;
    const hr = ROOT.querySelector(".fo").getBoundingClientRect(), ar = anchor.getBoundingClientRect();
    m.style.top = ar.bottom - hr.top + 6 + "px";
    const left = Math.min(ar.right - hr.left - 220, hr.width - 230);
    m.style.left = Math.max(8, left) + "px";
    m.querySelectorAll("[data-mi]").forEach((a) => (a.onclick = (e) => { e.stopPropagation(); m.hidden = true; items[+a.dataset.mi].run(); }));
  }
  const closeMenus = () => { $(".fo-float-menu").hidden = true; $(".fo-range-menu").hidden = true; };

  /* ---------------- tooltip ---------------- */
  let tip = null;
  function showTip(el, text) {
    if (!text) return;
    if (!tip) { tip = document.createElement("div"); tip.className = "fo-tip"; ROOT.querySelector(".fo").appendChild(tip); }
    tip.innerHTML = text; tip.hidden = false;
    const r = el.getBoundingClientRect();
    tip.style.left = Math.min(r.left, window.innerWidth - 300) + "px";
    tip.style.top = r.bottom + 8 + "px";
  }
  const hideTip = () => { if (tip) tip.hidden = true; };

  /* ---------------- KPI cards ---------------- */
  const KPIS = [
    { key: "active_projects", label: "Active Projects", sub: "Across the project portfolio", icon: "building", c: "blue" },
    { key: "overdue_milestones", label: "Overdue Milestones", sub: "Require follow-up", icon: "calclock", c: "orange" },
    { key: "pending_approvals", label: "Pending Approvals", sub: "Awaiting a decision", icon: "filecheck", c: "purple" },
    { key: "projects_at_risk", label: "Projects at Risk", sub: "Management review required", icon: "alert", c: "red" },
    { key: "open_variations", label: "Open Variations", sub: "Awaiting commercial action", icon: "filediff", c: "sky" },
  ];
  function kpiSkeleton() {
    $("[data-w='kpis']").innerHTML = KPIS.map((k) => `<div class="fo-kpi c-${k.c}"><div class="fo-kpi-ico fo-skel"></div><div class="fo-kpi-body"><div class="fo-skel" style="height:14px;width:70%"></div><div class="fo-skel" style="height:34px;width:40%;margin:6px 0"></div><div class="fo-skel" style="height:12px;width:85%"></div></div></div>`).join("");
  }
  function renderKpis(d) {
    const k = d.kpis;
    $("[data-w='kpis']").innerHTML = KPIS.map((x, i) => {
      let extra = "";
      if (x.key === "overdue_milestones" && k.overdue_tasks) extra = `<small>${k.overdue_tasks} overdue task${k.overdue_tasks === 1 ? "" : "s"} in total</small>`;
      return `<div class="fo-kpi c-${x.c}" data-k="${i}" role="button" tabindex="0">
        <div class="fo-kpi-ico">${ic(x.icon, "lg")}</div>
        <div class="fo-kpi-body"><span class="fo-kpi-label">${__(x.label)}</span><span class="fo-kpi-val">${k[x.key] ?? 0}</span><span class="fo-kpi-sub">${__(x.sub)}${extra}</span></div>
        <button class="fo-dots" data-kdots="${i}" aria-label="More">${ic("dots")}</button></div>`;
    }).join("");
    $$("[data-k]").forEach((el) => {
      const x = KPIS[+el.dataset.k];
      el.onclick = (e) => { if (e.target.closest("[data-kdots]")) return; kpiDetail(x.key); };
      el.onkeydown = (e) => { if (e.key === "Enter") kpiDetail(x.key); };
    });
    $$("[data-kdots]").forEach((b) => (b.onclick = (e) => {
      e.stopPropagation();
      const x = KPIS[+b.dataset.kdots];
      openMenu(b, [{ label: __("View details"), icon: "list", run: () => kpiDetail(x.key) }, { label: __("Open in list view"), icon: "open", run: () => kpiList(x.key) }]);
    }));
  }
  function kpiList(key) {
    const names = (S.data.projects || []).map((p) => p.name);
    if (key === "active_projects" || key === "projects_at_risk") return goList("Project", projectListOpts());
    if (key === "overdue_milestones") return goList("Task", { project: ["in", names], is_milestone: 1, status: ["not in", ["Completed", "Cancelled"]], exp_end_date: ["<", ymd(today())] });
    if (key === "pending_approvals") return goList("Material Request", { docstatus: 0 });
    if (key === "open_variations") return goList("Fit Out Variation", Object.assign({ status: ["not in", ["Approved", "Rejected", "Cancelled"]] }, S.company ? { company: S.company } : {}));
  }
  function detailDialog(title, rowsHtml, emptyText, footer) {
    const d = new frappe.ui.Dialog({ title, size: "large", fields: [{ fieldname: "b", fieldtype: "HTML" }] });
    d.fields_dict.b.$wrapper.html(rowsHtml ? `<div class="list-group">${rowsHtml}</div>${footer || ""}` : `<div class="text-muted" style="padding:14px">${emptyText}</div>${footer || ""}`);
    d.fields_dict.b.$wrapper.find("[data-dt]").on("click", function () { d.hide(); if (this.dataset.dt === "Project") openProject(this.dataset.dn); else goForm(this.dataset.dt, this.dataset.dn); });
    d.show();
    return d;
  }
  const li = (dt, dn, main, side) => `<a class="list-group-item list-group-item-action d-flex justify-content-between align-items-center" style="cursor:pointer;gap:14px" data-dt="${esc(dt)}" data-dn="${esc(dn)}"><span>${main}</span><span class="text-muted small text-right">${side || ""}</span></a>`;
  function kpiDetail(key) {
    const d = S.data; if (!d) return;
    const pr = d.projects || [];
    if (key === "active_projects")
      return detailDialog(__("Active Projects"), pr.map((p) => li("Project", p.name, `<b>${esc(p.name)}</b> · ${esc(p.project_name)}`, `${esc(p.stage)} · ${Math.round(p.progress)}%`)).join(""), __("No active projects in this range."));
    if (key === "projects_at_risk")
      return detailDialog(__("Projects at Risk"), pr.filter((p) => p.health !== "On Track").map((p) => li("Project", p.name, `<b>${esc(p.project_name)}</b><br><span class="small text-muted">${esc((p.health_reasons || []).join(" · "))}</span>`, `<span class="indicator-pill ${p.health === "Delayed" ? "red" : "orange"}">${esc(p.health)}</span>`)).join(""), __("No projects at risk."));
    if (key === "overdue_milestones") {
      const a = (d.actions || []).filter((x) => x.kind === "milestone");
      return detailDialog(__("Overdue Milestones"), a.map((x) => li(x.doctype, x.docname, `<b>${esc(x.project_name)}</b><br><span class="small">${esc(x.next)}</span>`, esc(x.docname))).join(""),
        __("No overdue milestones. Tick “Is Milestone” on key tasks to track them here.") + (d.kpis.overdue_tasks ? `<br><br>${d.kpis.overdue_tasks} ${__("ordinary task(s) are overdue across these projects.")}` : ""));
    }
    if (key === "pending_approvals") {
      const a = (d.actions || []).filter((x) => ["material", "po", "expense"].includes(x.kind));
      const b = d.kpis.pending_breakdown || {};
      return detailDialog(__("Pending Approvals"), a.map((x) => li(x.doctype, x.docname, `<b>${esc(x.title)}</b> · ${esc(x.project_name)}`, esc(x.docname))).join(""), __("Nothing is waiting for approval."),
        `<div class="text-muted small" style="padding:10px 2px">${Object.keys(b).map((k) => `${esc(k)}: <b>${b[k]}</b>`).join(" &nbsp;·&nbsp; ")}</div>`);
    }
    if (key === "open_variations") {
      const a = (d.actions || []).filter((x) => x.kind === "variation");
      const dlg = detailDialog(__("Open Variations"), a.map((x) => li(x.doctype, x.docname, `<b>${esc(x.title)}</b> · ${esc(x.project_name)}<br><span class="small">${esc(x.next)}</span>`, esc(x.docname))).join(""), __("No open variations."));
      dlg.set_primary_action(__("New Variation"), () => { dlg.hide(); frappe.new_doc("Fit Out Variation"); });
    }
  }

  /* ---------------- portfolio ---------------- */
  const MAX_ROWS = 8;
  function portfolioSkeleton() {
    $("[data-w='portfolio']").innerHTML = `<table class="fo-table"><thead>${headRow()}</thead><tbody>${Array.from({ length: 5 }, () => `<tr><td colspan="9"><div class="fo-skel" style="height:18px"></div></td></tr>`).join("")}</tbody></table>`;
  }
  const headRow = () => `<tr><th>${__("Project ID")}</th><th>${__("Project")}</th><th>${__("Client")}</th><th>${__("Current Stage")}</th><th>${__("Progress")}</th><th>${__("Health")}</th><th>${__("Target Handover")}</th><th>${__("Project Manager")}</th><th style="width:48px"></th></tr>`;
  function renderPortfolio(d) {
    const pr = d.projects || [];
    const box = $("[data-w='portfolio']");
    if (!pr.length) {
      const fit = S.scope === "fitout";
      box.innerHTML = `<div class="fo-empty"><b>${fit ? __("No fit-out projects yet") : __("No active projects")}</b>
        <span>${fit ? __("Tick “Fit Out Project” on a project to add it to this portfolio, or switch to All Projects.") : __("No open projects fall within the selected dates.")}</span>
        <div>${fit ? `<a class="fo-btn ghost" data-act="scope-all">${__("Show all projects")}</a> ` : ""}<a class="fo-btn" data-act="new-project">${ic("plus", "sm")}${__("New Project")}</a></div></div>`;
