    const more = pr.length > MAX_ROWS ? `<div class="fo-more">${__("Showing")} ${MAX_ROWS} ${__("of")} ${pr.length} — <a data-act="all-projects">${__("view all")}</a></div>` : "";
    box.innerHTML = `<table class="fo-table"><thead>${headRow()}</thead><tbody>${rows}</tbody></table>${more}`;
    box.querySelectorAll("tr[data-i]").forEach((tr) => (tr.onclick = (e) => { if (e.target.closest("[data-rdots]")) return; openProject(pr[+tr.dataset.i].name); }));
    box.querySelectorAll("[data-rdots]").forEach((b) => (b.onclick = (e) => { e.stopPropagation(); rowMenu(b, pr[+b.dataset.rdots]); }));
    requestAnimationFrame(() => box.querySelectorAll(".fo-bar i").forEach((b) => (b.style.width = b.dataset.w + "%")));
  }
  function rowHtml(p, i) {
    const t0 = today();
    const col = STAGE_COLOR[p.stage] || "#2563EB";
    const late = p.target && toDate(p.target) < t0;
    return `<tr data-i="${i}">
      <td class="fo-pid">${esc(p.name)}</td>
      <td><span class="fo-pname" title="${esc(p.project_name)}">${esc(p.project_name)}</span></td>
      <td><span class="fo-client" title="${esc(p.customer || "")}">${p.customer ? esc(p.customer) : '<span class="fo-muted">—</span>'}</span></td>
      <td><span class="fo-stage ${p.stage_auto ? "auto" : ""}" ${p.stage_auto ? `data-tip="${esc(__("Estimated from progress. Set Fit Out Stage on the project to fix it."))}"` : ""}>${esc(p.stage || "—")}</span></td>
      <td><div class="fo-prog"><div class="fo-bar"><i data-w="${Math.max(0, Math.min(100, p.progress))}" style="background:${col}"></i></div><b>${Math.round(p.progress)}%</b></div></td>
      <td><span class="fo-health ${hcls(p.health)} ${p.health_manual ? "manual" : ""}" data-tip="${esc((p.health_reasons || []).join("<br>") || __("Dates, progress, milestones and deliveries are all on plan."))}">${esc(__(p.health))}</span></td>
      <td><span class="fo-date ${late ? "late" : ""}">${p.target ? fmtD(p.target) : '<span class="fo-muted">—</span>'}</span></td>
      <td class="fo-pm" title="${esc(p.manager || "")}">${p.manager ? esc(shortName(p.manager)) : '<span class="fo-muted">—</span>'}</td>
      <td><button class="fo-row-dots" data-rdots="${i}" aria-label="Actions">${ic("dots")}</button></td></tr>`;
  }
  function rowMenu(anchor, p) {
    openMenu(anchor, [
      { label: __("Open project page"), icon: "building", run: () => openProject(p.name) },
      { label: __("Open project form"), icon: "open", run: () => goForm("Project", p.name) },
      { label: __("View tasks"), icon: "list", run: () => goList("Task", { project: p.name }) },
      { label: __("Update stage & health"), icon: "edit", run: () => editProject(p, S.view === "projects" ? loadProjects : refresh) },
      { label: __("Raise variation"), icon: "plus", run: () => frappe.new_doc("Fit Out Variation", { project: p.name }) },
      { label: __("Purchase orders"), icon: "cart", run: () => goList("Purchase Order", { project: p.name }) },
    ]);
  }
  function editProject(p, after) {
    const d = new frappe.ui.Dialog({
      title: `${esc(p.name)} · ${esc(p.project_name)}`,
      fields: [
        { fieldname: "fo_is_fitout", label: __("Fit Out Project"), fieldtype: "Check", default: p.is_fitout ? 1 : 0 },
        { fieldname: "fo_stage", label: __("Fit Out Stage"), fieldtype: "Select", options: "\nEnquiry & Requirements\nEstimation & BOQ\nContract Award\nDesign & Approvals\nProcurement\nSite Execution\nCommercial Review\nHandover & Closure\nCompleted", default: p.stage_auto ? "" : p.stage },
        { fieldtype: "Column Break" },
        { fieldname: "fo_health", label: __("Health Override"), fieldtype: "Select", options: "\nOn Track\nAt Risk\nDelayed", default: p.health_manual ? p.health : "", description: __("Leave empty to calculate automatically.") },
        { fieldname: "percent_complete", label: __("% Completed"), fieldtype: "Percent", default: p.progress, description: __("Only used if the project's % Complete Method is Manual.") },
      ],
      primary_action_label: __("Save"),
      async primary_action(v) {
        try {
          const vals = { fo_is_fitout: v.fo_is_fitout ? 1 : 0, fo_stage: v.fo_stage || "", fo_health: v.fo_health || "" };
          if (Math.round(v.percent_complete || 0) !== Math.round(p.progress || 0)) vals.percent_complete = v.percent_complete || 0;
          await frappe.call({ method: "frappe.client.set_value", args: { doctype: "Project", name: p.name, fieldname: vals } });
          d.hide(); frappe.show_alert({ message: __("Project updated"), indicator: "green" }); S.dataStale = true; (after || refresh)();
        } catch (e) { /* frappe shows the error */ }
      },
    });
    d.show();
  }

  /* ---------------- priority actions ---------------- */
  const ACT_ICON = { material: ["bang", true], milestone: ["flag", false], variation: ["filetext", false], po: ["cart", false],
    delivery: ["truck", false], handover: ["calclock", false], invoice: ["filetext", false], expense: ["receipt", false] };
  function actionsSkeleton() { $("[data-w='actions']").innerHTML = Array.from({ length: 4 }, () => `<div class="fo-skel" style="height:130px;border-radius:14px"></div>`).join(""); }
  function renderActions(d) {
    const acts = d.actions || [];
    const box = $("[data-w='actions']");
    if (!acts.length) { box.innerHTML = `<div class="fo-empty"><b>${__("Nothing needs attention")}</b><span>${__("Delayed deliveries, overdue invoices, pending approvals and variations will appear here.")}</span></div>`; return; }
    // one card per kind first so the row shows a spread of issues, then fill by severity
    const picked = [], seen = {};
    acts.forEach((a) => { if (picked.length < 4 && !seen[a.kind]) { seen[a.kind] = 1; picked.push(a); } });
    acts.forEach((a) => { if (picked.length < 4 && !picked.includes(a)) picked.push(a); });
    picked.sort((a, b) => a.sev - b.sev);
    box.innerHTML = picked.map((a, i) => {
      const [icon, solid] = ACT_ICON[a.kind] || ["filetext", false];
      return `<div class="fo-act k-${a.kind}" data-a="${i}" role="button" tabindex="0">
        <div class="fo-act-ico ${solid ? "solid" : ""}">${ic(icon, "lg")}</div>
        <div class="fo-act-body"><b>${esc(__(a.title))}</b><span>${__("Project")}: ${esc(a.project)}</span><p>${__("Next action")}: ${esc(a.next)}</p></div>
        <button class="fo-dots" data-adots="${i}" aria-label="More">${ic("dots")}</button></div>`;
    }).join("");
    box.querySelectorAll("[data-a]").forEach((el) => {
      const a = picked[+el.dataset.a];
      el.onclick = (e) => { if (e.target.closest("[data-adots]")) return; goForm(a.doctype, a.docname); };
      el.onkeydown = (e) => { if (e.key === "Enter") goForm(a.doctype, a.docname); };
      el.querySelector("[data-adots]").onclick = (e) => {
        e.stopPropagation();
        openMenu(e.currentTarget, [{ label: `${__("Open")} ${a.docname}`, icon: "open", run: () => goForm(a.doctype, a.docname) },
          { label: __("Open project"), icon: "building", run: () => openProject(a.project) }]);
      };
    });
  }
  function allActions() {
    const acts = (S.data && S.data.actions) || [];
    const rows = acts.map((a) => li(a.doctype, a.docname, `<b>${esc(a.title)}</b> · ${esc(a.project)} ${esc(a.project_name)}<br><span class="small">${esc(a.next)}</span>`, esc(a.docname))).join("");
    detailDialog(`${__("Priority Actions")} (${(S.data && S.data.action_total) || 0})`, rows, __("Nothing needs attention."));
  }

  /* =================== VIEWS & NAVIGATION =================== */
  // "Are we on the Fit Out page?" The route string captured at load can be stale (e.g. the block was
  // re-rendered mid-navigation), so a visible block also counts and re-learns its route and path.
  const curRoute = () => (frappe.get_route_str && frappe.get_route_str()) || "";
  const onOurRoute = () => {
    if (!HOST.isConnected) return false;
    if (curRoute() === S.routeStr) return true;
    if (HOST.getClientRects().length) { S.routeStr = curRoute(); S.basePath = window.location.pathname.replace(/\/+$/, ""); sideActive = null; return true; }
    return false;
  };
  function setView(v) {
    S.view = v;
    $$(".fo-view").forEach((el) => (el.hidden = el.dataset.view !== v));
    closeMenus(); hideTip();
    syncUrl(); syncSide();
    try { if (HOST.getBoundingClientRect().top < 0) HOST.scrollIntoView({ block: "start" }); } catch (e) {}
  }
  function syncUrl() {
    try {
      const u = new URL(window.location.href);
      ["fo_view", "fo_project", "fo_tab", "fo_boq", "fo_btab", "fo_pproj", "fo_eproj", "fo_xproj"].forEach((k) => u.searchParams.delete(k));
      if (S.view === "projects" || S.view === "boqs" || S.view === "proc" || S.view === "exec") u.searchParams.set("fo_view", S.view);
      if (S.view === "proc" && PC.project) u.searchParams.set("fo_pproj", PC.project);
      if (S.view === "exec" && ES.project) u.searchParams.set("fo_eproj", ES.project);
      if (isX(S.view)) { u.searchParams.set("fo_view", xSideKey()); if (XS[S.view].project) u.searchParams.set("fo_xproj", XS[S.view].project); }
      if (S.view === "boq" && BQ.name) { u.searchParams.set("fo_boq", BQ.name); if (BQ.tab !== "boq") u.searchParams.set("fo_btab", BQ.tab); }
      if (S.view === "project" && PJ.name) { u.searchParams.set("fo_project", PJ.name); if (PJ.tab !== "overview") u.searchParams.set("fo_tab", PJ.tab); }
      const next = u.pathname + u.search + u.hash;
      if (next !== window.location.pathname + window.location.search + window.location.hash) window.history.replaceState(window.history.state, "", next);
    } catch (e) {}
  }
  function readUrl() {
    let q; try { q = new URLSearchParams(window.location.search); } catch (e) { q = new URLSearchParams(); }
    const ro = frappe.route_options || {};
    const get = (k) => q.get(k) || ro[k] || null;
    const r = { view: get("fo_view"), project: get("fo_project"), tab: get("fo_tab"), boq: get("fo_boq"), btab: get("fo_btab"), pproj: get("fo_pproj"), eproj: get("fo_eproj"), xproj: get("fo_xproj") };
    ["fo_view", "fo_project", "fo_tab", "fo_boq", "fo_btab", "fo_pproj", "fo_eproj", "fo_xproj"].forEach((k) => { try { delete ro[k]; } catch (e) {} });
    return r;
  }
  function applyUrl() {
    const r = readUrl();
    if (r.boq) openBoq(r.boq, r.btab);
    else if (r.project) openProject(r.project, r.tab);
    else if (r.view === "projects") showProjects();
    else if (r.view === "boqs") showBoqs();
    else if (r.view === "proc") showProc(r.pproj);
    else if (r.view === "exec") showExec(r.eproj);
    else if (xRouteOk(r.view)) xRoute(r.view, r.xproj);
    else if (S.view !== "dash") showDash();
  }
  function showDash() { setView("dash"); if (!S.data || S.dataStale) refresh(); }

  /* ---- workspace sidebar: Dashboard / Projects items open views in place ---- */
  const SIDE_SEL = ".body-sidebar, .body-sidebar-container, .desk-sidebar, .layout-side-section";
  const sideAnchors = () => Array.from(document.querySelectorAll(SIDE_SEL.split(", ").map((s) => s + " a[href]").join(", ")));
  function anchorTarget(a) {
    let u; try { u = new URL(a.getAttribute("href") || "", window.location.origin); } catch (e) { return null; }
    if (u.origin === window.location.origin && /^\/[a-z]+\/project$/.test(u.pathname.replace(/\/+$/, "")) && !u.search) return { key: "projects", view: "projects", project: null };
    if (u.origin === window.location.origin && /^\/[a-z]+\/fit-out-work-package$/.test(u.pathname.replace(/\/+$/, "")) && !u.search) return { key: "exec", view: "exec", project: null };
    if (u.origin === window.location.origin && /^\/[a-z]+\/purchase-order$/.test(u.pathname.replace(/\/+$/, "")) && !u.search) return { key: "proc", view: "proc", project: null };
    if (u.origin === window.location.origin && /^\/[a-z]+\/fit-out-boq$/.test(u.pathname.replace(/\/+$/, "")) && !u.search) return { key: "boqs", view: "boqs", project: null };   // sidebar "Projects" (DocType link) opens the in-workspace list
    { const xm_ = u.origin === window.location.origin && !u.search && u.pathname.replace(/\/+$/, "").match(/^\/[a-z]+\/([a-z-]+)$/); if (xm_ && XPATH[xm_[1]]) return { key: XPATH[xm_[1]], view: XPATH[xm_[1]], project: null }; }
    if (u.origin !== window.location.origin || u.pathname.replace(/\/+$/, "") !== S.basePath) return null;
    const p = u.searchParams.get("fo_project"), v = u.searchParams.get("fo_view"), bq = u.searchParams.get("fo_boq");
    return { key: v === "proc" || v === "exec" ? v : bq || v === "boqs" ? "boqs" : p || v === "projects" ? "projects" : "", view: v, project: p, boq: bq };
  }
  let sideActive = null;
  const ACTIVE_RE = /activ|select|current|highlight/i;
  const chainOf = (a) => { const c = [a]; let e = a.parentElement; for (let i = 0; i < 3 && e; i++) { c.push(e); e = e.parentElement; } return c; };
  function detectSideActive(items) {
    const chains = items.map(({ a }) => chainOf(a));
    for (let lvl = 0; lvl < 4; lvl++) {
      const els = chains.map((c) => c[lvl]);
      if (els.some((e) => !e) || new Set(els).size !== els.length) continue;
      const counts = {};
      els.forEach((el) => new Set(el.classList).forEach((k) => (counts[k] = (counts[k] || 0) + 1)));
      const uniq = Object.keys(counts).filter((k) => counts[k] === 1 && ACTIVE_RE.test(k));
      if (uniq.length) return { lvl, cls: uniq };
    }
    return null;
  }
  function syncSide() {
    if (!onOurRoute()) return;
    const want = isX(S.view) ? xSideKey() : S.view === "dash" ? "" : S.view === "proc" || S.view === "exec" ? S.view : S.view === "boqs" || S.view === "boq" ? "boqs" : "projects";
    const items = sideAnchors().map((a) => ({ a, t: anchorTarget(a) })).filter((x) => x.t);
    if (items.length < 2) return;
    if (!sideActive) sideActive = detectSideActive(items);
    items.forEach(({ a, t }) => {
      const isOn = t.key === want;
      const ch = chainOf(a);
      if (sideActive) { const el = ch[sideActive.lvl]; if (el) sideActive.cls.forEach((k) => el.classList.toggle(k, isOn)); }
      if (!isOn) ch.forEach((el) => Array.from(el.classList).forEach((k) => { if (ACTIVE_RE.test(k) && el.querySelectorAll("a[href]").length <= 1) el.classList.remove(k); }));
      if (isOn) a.setAttribute("aria-current", "page"); else a.removeAttribute("aria-current");
      a.toggleAttribute("data-fo-active", isOn);
    });
    if (!sideActive && !document.getElementById("fo-side-active-css")) {
      const st = document.createElement("style"); st.id = "fo-side-active-css";
      st.textContent = "a[data-fo-active]{background:var(--sidebar-select-color, var(--subtle-fg, #f3f3f3));border-radius:var(--border-radius-md, 8px);font-weight:500}";
      document.head.appendChild(st);
    }
  }
  const pathOf = (x) => { try { return new URL(x.getAttribute("href") || "", window.location.origin).pathname.replace(/\/+$/, ""); } catch (e) { return ""; } };
  // the sidebar holding this link also links to our workspace page (i.e. it is the Fit Out sidebar)
  const sideIsOurs = (a) => { const sb = a.closest(SIDE_SEL); return !!sb && Array.from(sb.querySelectorAll("a[href]")).some((x) => pathOf(x) === S.basePath); };
  function onSideClick(e) {
    if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    const a = e.target && e.target.closest ? e.target.closest("a[href]") : null;
    if (!a || !a.closest(SIDE_SEL)) return;
    const t = anchorTarget(a);
    if (!t || !HOST.isConnected) return;
    if (!onOurRoute()) {
      // On another page but the Fit Out sidebar is showing: open the Fit Out view instead of the plain list.
      if (!t.view || !S.routeStr || !sideIsOurs(a)) return;
      e.preventDefault(); e.stopImmediatePropagation();
      frappe.route_options = { fo_view: t.view };
      frappe.set_route(...S.routeStr.split("/"));
      return;
    }
    e.preventDefault(); e.stopImmediatePropagation();
    if (t.boq) openBoq(t.boq); else if (t.project) openProject(t.project); else if (t.view === "projects") showProjects(); else if (t.view === "boqs") showBoqs(); else if (t.view === "proc") showProc(); else if (t.view === "exec") showExec(); else if (xRouteOk(t.view)) xRoute(t.view); else showDash();
  }

  /* =================== PROJECTS LIST =================== */
  const PL = { scope: null, rows: null, q: "" };
  function showProjects() {
    setView("projects");
    if (!PL.scope) PL.scope = S.scope || "fitout";
    $$("[data-pscope]").forEach((b) => b.classList.toggle("on", b.dataset.pscope === PL.scope));
    loadProjects();
  }
  async function loadProjects() {
    const box = $("[data-w='plist']");
    box.innerHTML = `<table class="fo-table"><thead>${headRow()}</thead><tbody>${Array.from({ length: 6 }, () => `<tr><td colspan="9"><div class="fo-skel" style="height:18px"></div></td></tr>`).join("")}</tbody></table>`;
    try {
      const d = await api("hipersign_fitout_dashboard", { company: S.company, from_date: "1900-01-01", to_date: "2999-12-31", scope: PL.scope });
      PL.rows = d.projects || []; PL.fitout_total = d.fitout_total;
      renderProjects();
    } catch (e) { box.innerHTML = `<div class="fo-err" style="margin:14px">${__("Couldn't load projects")}: ${esc(e.message)}</div>`; }
  }
  function renderProjects() {
    const box = $("[data-w='plist']");
    const q = PL.q.trim().toLowerCase();
    const rows = (PL.rows || []).filter((p) => !q || [p.name, p.project_name, p.customer, p.manager, p.stage].some((x) => String(x || "").toLowerCase().includes(q)));
    if (!rows.length) {
      box.innerHTML = `<div class="fo-empty"><b>${q ? __("No matching projects") : PL.scope === "fitout" ? __("No fit-out projects yet") : __("No open projects")}</b>
        <span>${PL.scope === "fitout" && !q ? __("Tick “Fit Out Project” on a project, or switch to All Projects.") : ""}</span></div>`;
      return;
    }
    box.innerHTML = `<table class="fo-table"><thead>${headRow()}</thead><tbody>${rows.map((p, i) => rowHtml(p, i)).join("")}</tbody></table>`;
    box.querySelectorAll("tr[data-i]").forEach((tr) => (tr.onclick = (e) => { if (e.target.closest("[data-rdots]")) return; openProject(rows[+tr.dataset.i].name); }));
    box.querySelectorAll("[data-rdots]").forEach((b) => (b.onclick = (e) => { e.stopPropagation(); rowMenu(b, rows[+b.dataset.rdots]); }));
    requestAnimationFrame(() => box.querySelectorAll(".fo-bar i").forEach((b) => (b.style.width = b.dataset.w + "%")));
  }

  /* =================== PROJECT PAGE =================== */
  const TABS = [["overview", "Overview"], ["estimation", "Estimation & BOQ"], ["procurement", "Procurement"], ["inventory", "Inventory"],
    ["subcontractors", "Subcontractors"], ["execution", "Site Execution"], ["variations", "Variations"], ["invoicing", "Invoicing"],
    ["documents", "Documents"], ["costs", "Costs"], ["activity", "Activity History"]];
  const PJ = { name: null, tab: "overview", head: null, data: {}, seq: 0, currency: null };
  const money = (v) => fmtMoney(v, PJ.currency);
  const bcls = (s) => "b-" + String(s || "").toLowerCase().replace(/[^a-z]/g, "");
  const badge = (s) => `<span class="pj-badge ${bcls(s)}">${esc(__(s || ""))}</span>`;
  const dash = '<span class="fo-muted">—</span>';
  function openProject(name, tab) {
    if (!name) return;
    const same = PJ.name === name && S.view === "project";
    PJ.name = name; PJ.tab = TABS.some((t) => t[0] === tab) ? tab : "overview";
    if (!same) { PJ.data = {}; PJ.head = null; }
    setView("project");
    renderShell();
    loadProject();
  }
  function reloadProject() { PJ.data = {}; loadProject(); }
  function renderShell() {
    const h = PJ.head;
    $(".pj").innerHTML = `
      <div class="pj-top">
        <div class="pj-crumb"><a data-act="pj-back">${ic("back")}<span class="t">${__("Projects")}</span></a><i>/</i><b>${h ? `${esc(h.name)} — ${esc(h.project_name)}` : esc(PJ.name)}</b></div>
        <div class="pj-actions"><button data-act="pj-actions">${__("Actions")}</button><button data-act="pj-actions" aria-label="More">${ic("dots")}</button></div>
      </div>
      <div class="pj-hero-slot">${h ? heroHtml(h) : `<div class="fo-skel pj-skel-hero"></div>`}</div>
      <nav class="pj-tabs" role="tablist">${TABS.map(([k, l]) => `<button role="tab" data-tab="${k}" class="${PJ.tab === k ? "on" : ""}">${__(l)}</button>`).join("")}</nav>
      <div class="pj-body"></div>`;
    $$(".pj-tabs [data-tab]").forEach((b) => (b.onclick = () => { PJ.tab = b.dataset.tab; $$(".pj-tabs [data-tab]").forEach((x) => x.classList.toggle("on", x === b)); syncUrl(); renderTab(); }));
    if (h) bindHero();
    renderTab();
  }
  function heroHtml(h) {
    const st = h.status === "Open" ? ["", __("Active Project")] : h.status === "Completed" ? ["s-done", __("Completed")] : h.status === "On hold" ? ["s-hold", __("On Hold")] : ["s-cancel", __(h.status)];
    const late = h.target && toDate(h.target) < today() && h.status === "Open";
    const initials = (h.project_name || h.name).split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0]).join("").toUpperCase();
    const meta = (icon, label, val) => `<div class="pj-mi"><span>${ic(icon)}</span><div><small>${label}</small><b class="${val ? "" : "muted"}" title="${esc(val || "")}">${esc(val || __("Not set"))}</b></div></div>`;
