  function summaryHtml(d) {
    const s = d.summary, c = d.currency, b = d.boq;
    const row = (l, v, cls) => `<div class="bq-sr ${cls || ""}"><span>${l}</span><b>${v}</b></div>`;
    const price = s.selling_price || 0;
    const m = s.gross_margin;
    const mcls = !price ? "" : m < 0 ? "neg" : m < s.target_margin ? "warn" : "pos";
    return `<section class="pj-sec bq-sum"><div class="bq-h"><span class="bq-hi">${ic("calc")}</span><h3>${__("Estimate Summary")}</h3>${isLocked(b) ? "" : `<a data-act="bq-pricing">${ic("edit", "sm")}${__("Edit")}</a>`}</div>
      ${row(__("Direct Material Cost"), cur2(s.material, c))}
      ${row(__("Direct Labour Cost"), cur2(s.labour, c))}
      ${row(__("Subcontractor Cost"), cur2(s.subcontract, c))}
      ${row(__("Other Direct Costs"), cur2(s.other, c))}
      ${row(__("Total Estimated Direct Cost"), cur2(s.direct, c), "hl blue")}
      ${row(`${__("Overhead Allocation")} <small>${flt(s.overhead_percent)}%</small>`, cur2(s.overhead, c))}
      ${row(__("Total Estimated Project Cost"), cur2(s.project_cost, c), "hl blue")}
      ${price ? row(__("Proposed Selling Price (Before Tax)"), cur2(price, c), "hl purple")
        : `<div class="bq-sr hl purple"><span>${__("Proposed Selling Price (Before Tax)")}<small>${__("Suggested at {0}% margin", [flt(s.target_margin)])}</small></span><b>${cur2(s.suggested_price, c)}</b></div>`}
      ${row(__("Indicative Gross Profit"), price ? cur2(s.gross_profit, c) : "—", "hl green")}
      <div class="bq-sr bq-margin ${mcls}"><span>${__("Indicative Gross Margin")}</span><b>${price ? flt(m).toFixed(1) + "%" : "—"}</b></div>
      ${!price && !isLocked(b) ? `<div class="bq-note">${__("No selling price set yet.")} <a data-act="bq-pricing">${__("Set price")}</a></div>` : ""}
      ${price && m < s.target_margin ? `<div class="bq-note warn">${ic("alert", "sm")}${__("Margin is below the {0}% target.", [flt(s.target_margin)])}</div>` : ""}
    </section>`;
  }
  function historyHtml(d) {
    const steps = d.steps.map((s, i) => {
      const done = s.status === "Completed", est = s.status === "Established", rej = s.status === "Rejected";
      const cur = est || s.status === "In Progress" || s.status === "In Review";
      const dot = done ? ic("check", "sm") : String(i + 1);
      const pill = done ? "done" : est || cur ? "cur" : rej ? "rej" : "";
      return `<div class="pj-step ${done ? "done" : ""} ${cur ? "cur" : ""} ${rej ? "rej" : ""}" data-bstep="${esc(s.key)}" role="button" tabindex="0" title="${esc(s.by ? __("By {0}", [s.by]) : "")}">
        <span class="pj-dot">${dot}</span><b>${esc(__(s.label))}</b><span class="pj-st ${pill}">${esc(__(s.status))}</span><small>${s.date ? fmtD(s.date) : "—"}</small></div>`;
    }).join("");
    return `<section class="pj-sec bq-hist"><div class="bq-h"><span class="bq-hi">${ic("checksq")}</span><h3>${__("Estimate & Approval History")}</h3></div>
      <div class="pj-steps-wrap"><div class="pj-steps bq-steps">${steps}</div></div>
      ${d.boq.status === "Rejected" && d.boq.rejection_reason ? `<div class="bq-note neg">${ic("alert", "sm")}${__("Rejected")}: ${esc(d.boq.rejection_reason)}</div>` : ""}</section>`;
  }
  function baselineHtml(d) {
    const b = d.boq, est = b.budget_status && b.budget_status !== "Not Established";
    const kv = (l, v) => `<div><span>${l}</span>${v}</div>`;
    return `<section class="pj-sec bq-base"><div class="bq-h"><span class="bq-hi">${ic("database")}</span><h3>${__("Project Budget Baseline")}</h3></div>
      <div class="pj-kv bq-kv">
        ${kv(__("Baseline Reference"), `<b>${est ? esc(b.baseline_reference) : "—"}</b>`)}
        ${kv(__("Source"), `<b>${est ? esc(__(b.baseline_source)) : __("Not yet baselined")}</b>`)}
        ${kv(__("Budget Status"), `<span class="pj-badge ${est ? "b-completed" : "b-cancelled"}">${est ? __("Established") : __("Not Established")}</span>`)}
        ${est ? kv(__("Baseline Value"), `<b>${cur2(b.total_project_cost, d.currency)}</b>`) : ""}
        ${kv(__("Change Control"), `<b>${esc(__(b.change_control || "Approved Revisions Only"))}</b>`)}
      </div>
      ${!est && APPROVED.includes(b.status) ? `<div class="bq-note">${__("This estimate is approved.")} <a data-bstep="baseline_on" data-act="bq-step">${__("Establish the budget baseline")}</a></div>` : ""}</section>`;
  }

  /* ---------------- tabs ---------------- */
  function renderBoqTab() {
    const body = $(".bq-body"); if (!body || !BQ.d) return;
    BT[BQ.tab](BQ.d, body);
    body.querySelectorAll("[data-new]").forEach((x) => (x.onclick = () => (x.dataset.new === "upload" ? uploadBoqFile() : null)));
    requestAnimationFrame(() => body.querySelectorAll(".fo-bar i[data-w]").forEach((x) => (x.style.width = x.dataset.w + "%")));
  }
  const BT = {
    boq(d, body) {
      const b = d.boq, c = d.currency, items = d.items || [];
      const secs = [...new Set(items.map((x) => x.work_section || "General"))];
