            <button class="bq-icon" data-act="bq-tblmenu" aria-label="More">${ic("dots")}</button>
          </div></div>
        ${locked ? `<div class="bq-note lock">${ic("info", "sm")}<span>${b.status === "Superseded" ? __("This estimate was superseded by {0}.", [esc(b.superseded_by || "a newer revision")]) : __("This estimate is the approved budget baseline, so quantities and rates are locked.")}</span> <a data-act="bq-revise">${__("Create a revision")}</a></div>` : ""}
        ${items.length ? `<div class="pj-tbl-wrap"><table class="pj-tbl bq-tbl"><thead><tr><th class="n">#</th><th>${__("Work Section")}</th><th>${__("Description")}</th><th>${__("Unit")}</th><th class="r">${__("Quantity")}</th><th class="r">${__("Unit Rate")} (${esc(c)})</th><th class="r">${__("Amount")} (${esc(c)})</th><th class="d"></th></tr></thead>
          <tbody>${rows.map((x) => `<tr data-row="${esc(x.name)}"><td class="n">${x.idx}</td><td>${esc(x.work_section)}</td><td class="wrap">${esc(x.description || "")}${x.remarks ? `<small>${esc(x.remarks)}</small>` : ""}</td><td>${unitTxt(x.uom)}</td>
            <td class="r">${flt(x.qty).toLocaleString(undefined, { maximumFractionDigits: 3 })}</td><td class="r" data-tip="${esc(tip(x))}">${num2(x.unit_rate)}</td><td class="r">${num2(x.amount)}</td>
            <td class="d"><button class="fo-row-dots" data-rowmenu="${esc(x.name)}" aria-label="Actions">${ic("dots")}</button></td></tr>`).join("") ||
            `<tr><td colspan="8" class="pj-empty">${__("No items match.")}</td></tr>`}</tbody>
          <tfoot><tr><td colspan="6" class="r">${BQ.section || q ? __("Filtered Total") : __("Total BOQ Amount")} (${esc(c)})</td><td class="r"><b>${num2(total)}</b></td><td></td></tr></tfoot></table></div>`
        : `<div class="pj-empty">${__("No items yet.")} ${locked ? "" : `<a data-act="bq-add">${__("Add the first item")}</a>`}</div>`}
      </section>`;
      const sel = body.querySelector("[data-bq='section']"), inp = body.querySelector("[data-bq='q']");
      sel.onchange = () => { BQ.section = sel.value; renderBoqTab(); };
      inp.oninput = () => { BQ.q = inp.value; const pos = inp.selectionStart; renderBoqTab(); const n = $(".bq-body [data-bq='q']"); if (n) { n.focus(); n.setSelectionRange(pos, pos); } };
      body.querySelectorAll("tr[data-row]").forEach((tr) => (tr.onclick = (e) => { if (e.target.closest("[data-rowmenu]")) return; itemDialog(items.find((x) => x.name === tr.dataset.row)); }));
      body.querySelectorAll("[data-rowmenu]").forEach((x) => (x.onclick = (e) => { e.stopPropagation(); rowItemMenu(x, items.find((y) => y.name === x.dataset.rowmenu)); }));
    },
    cost(d, body) {
      const s = d.summary, c = d.currency, secs = d.sections || [];
      const dir = s.direct || 1;
      const parts = [["Material", s.material, "#2563EB"], ["Labour", s.labour, "#7C3AED"], ["Subcontractor", s.subcontract, "#F97316"], ["Other Direct", s.other, "#0EA5E9"]];
      body.innerHTML = tiles([{ l: __("Total Direct Cost"), v: cur2(s.direct, c) }, { l: __("Overhead") + ` (${flt(s.overhead_percent)}%)`, v: cur2(s.overhead, c) },
        { l: __("Total Project Cost"), v: cur2(s.project_cost, c) }, { l: __("Gross Margin"), v: s.selling_price ? flt(s.gross_margin).toFixed(1) + "%" : "—", s: s.selling_price ? cur2(s.gross_profit, c) : __("No selling price"), cls: s.selling_price ? (s.gross_margin < 0 ? "bad" : "good") : "" }]) +
        section(__("Cost Build-up"), null, "", `<div class="bq-stack">${parts.map((p) => `<i style="width:${(flt(p[1]) * 100) / dir}%;background:${p[2]}" title="${esc(__(p[0]))}"></i>`).join("")}</div>
          <div class="bq-legend">${parts.map((p) => `<span><i style="background:${p[2]}"></i>${__(p[0])} <b>${cur2(p[1], c)}</b> <small>${s.direct ? Math.round((flt(p[1]) * 100) / dir) : 0}%</small></span>`).join("")}</div>`) +
        section(__("Cost by Work Section"), secs.length, "", secs.length ? `<div class="pj-tbl-wrap"><table class="pj-tbl"><thead><tr><th>${__("Work Section")}</th><th class="r">${__("Material")}</th><th class="r">${__("Labour")}</th><th class="r">${__("Subcontractor")}</th><th class="r">${__("Other")}</th><th class="r">${__("Total")}</th><th>${__("Share")}</th></tr></thead>
          <tbody>${secs.map((x) => `<tr class="nolink"><td>${esc(x.section)}</td><td class="r">${num2(x.material)}</td><td class="r">${num2(x.labour)}</td><td class="r">${num2(x.subcontract)}</td><td class="r">${num2(x.other)}</td><td class="r"><b>${num2(x.amount)}</b></td><td>${pct((x.amount * 100) / dir)}</td></tr>`).join("")}</tbody>
          <tfoot><tr><td>${__("Total")}</td><td class="r">${num2(s.material)}</td><td class="r">${num2(s.labour)}</td><td class="r">${num2(s.subcontract)}</td><td class="r">${num2(s.other)}</td><td class="r"><b>${num2(s.direct)}</b></td><td></td></tr></tfoot></table></div>` : `<div class="pj-empty">${__("No items yet.")}</div>`);
    },
    quotation(d, body) {
      const q = d.quotations || [], s = d.summary, c = d.currency;
      const price = s.selling_price || s.suggested_price;
      body.innerHTML = tiles([{ l: __("Proposed Selling Price"), v: cur2(price, c), s: s.selling_price ? __("Before tax") : __("Suggested — no price set") },
        { l: __("Latest Quotation"), v: q[0] ? esc(q[0].name) : "—", s: q[0] ? esc(q[0].docstatus === 0 ? __("Draft") : __(q[0].status)) : __("Not raised yet") },
        { l: __("Quoted (net)"), v: q[0] ? cur2(q[0].net_total, q[0].currency) : "—", s: q[0] && price ? `${flt(q[0].net_total) >= price ? "+" : ""}${cur2(flt(q[0].net_total) - price, c)} ${__("vs proposed")}` : "" }]) +
        section(__("Quotations"), q.length, `<button class="fo-btn" data-act="bq-newquote">${ic("plus", "sm")}${__("Create Quotation")}</button>`,
          q.length ? `<div class="pj-tbl-wrap"><table class="pj-tbl"><thead><tr><th>${__("Quotation")}</th><th>${__("Date")}</th><th>${__("Valid Till")}</th><th>${__("Client")}</th><th>${__("Status")}</th><th class="r">${__("Net Total")}</th><th class="r">${__("Grand Total")}</th></tr></thead>
            <tbody>${q.map((x) => `<tr data-dt="Quotation" data-dn="${esc(x.name)}"><td><a class="lnk">${esc(x.name)}</a></td><td>${fmtD(x.transaction_date)}</td><td>${x.valid_till ? fmtD(x.valid_till) : dash}</td><td>${esc(x.customer_name || "")}</td><td>${docStatus(x)}</td><td class="r">${cur2(x.net_total, x.currency)}</td><td class="r">${cur2(x.grand_total, x.currency)}</td></tr>`).join("")}</tbody></table></div>`
            : `<div class="pj-empty">${__("No quotation has been raised from this estimate yet. Creating one adds a line per work section, priced from the proposed selling price.")}</div>`);
      body.querySelectorAll("tr[data-dt]").forEach((tr) => (tr.onclick = () => goForm(tr.dataset.dt, tr.dataset.dn)));
    },
    revisions(d, body) {
      const rv = d.revisions || [];
      body.innerHTML = section(__("Estimate Revisions"), rv.length, `<button class="fo-btn ghost" data-act="bq-revise">${ic("plus", "sm")}${__("New Revision")}</button>`,
        `<div class="pj-tbl-wrap"><table class="pj-tbl"><thead><tr><th>${__("Estimate")}</th><th>${__("Type")}</th><th>${__("Date")}</th><th>${__("Status")}</th><th>${__("Budget")}</th><th class="r">${__("Project Cost")}</th><th class="r">${__("Selling Price")}</th><th class="r">${__("Margin")}</th></tr></thead>
        <tbody>${rv.map((x) => { const [sl, sc] = estStatus(x); return `<tr data-boq="${esc(x.name)}" class="${x.name === d.boq.name ? "cur" : ""}"><td><a class="lnk">${esc(x.name)}</a>${x.name === d.boq.name ? ` <small class="fo-muted">${__("(this)")}</small>` : ""}</td><td>${esc(__(x.estimate_type || "Original"))}</td><td>${fmtD(x.estimate_date)}</td>
          <td><span class="pj-badge ${sc}">${esc(sl)}</span></td><td>${x.budget_status && x.budget_status !== "Not Established" ? `<span class="pj-badge b-baseline">${esc(__(x.budget_status))}</span>` : dash}</td>
          <td class="r">${cur2(x.total_project_cost, x.currency)}</td><td class="r">${flt(x.selling_price) ? cur2(x.selling_price, x.currency) : dash}</td><td class="r">${flt(x.selling_price) ? flt(x.gross_margin_percent).toFixed(1) + "%" : "—"}</td></tr>`; }).join("")}</tbody></table></div>
        <div class="bq-note">${ic("info", "sm")}<span>${__("A new revision copies this estimate. When a revision is approved by the client, the previous one is marked Superseded.")}</span></div>`);
      body.querySelectorAll("tr[data-boq]").forEach((tr) => (tr.onclick = () => { if (tr.dataset.boq !== BQ.name) openBoq(tr.dataset.boq, "revisions"); }));
    },
    attachments(d, body) {
      const f = d.files || [];
      const kb = (n) => (n > 1048576 ? (n / 1048576).toFixed(1) + " MB" : Math.max(1, Math.round(n / 1024)) + " KB");
      body.innerHTML = section(__("Attachments"), f.length, btn("upload", __("Upload"), " "), f.length ? `<div class="pj-files">${f.map((x) => {
        const ext = (x.file_name || "").split(".").pop().toLowerCase();
        const img = ["png", "jpg", "jpeg", "gif", "webp", "svg"].includes(ext);
        return `<a class="pj-file" href="${esc(x.file_url)}" target="_blank" rel="noopener"><span class="th">${img ? `<img src="${esc(x.file_url)}" alt="">` : esc(ext.toUpperCase().slice(0, 4))}</span>
          <div><b title="${esc(x.file_name)}">${esc(x.file_name)}</b><span>${kb(flt(x.file_size))} · ${fmtD(x.creation)}${x.is_private ? " · " + __("Private") : ""}</span><span>${esc(x.owner_name || "")}</span></div></a>`;
      }).join("")}</div>` : `<div class="pj-empty">${__("No attachments yet. Upload drawings, supplier quotes and take-off sheets here.")}</div>`);
    },
    notes(d, body) {
      const b = d.boq;
      const txt = (v) => (v ? esc(v).replace(/\n/g, "<br>") : `<span class="fo-muted">${__("Not recorded")}</span>`);
