          <div class="two"><div><h4>${__("Assumptions")}</h4><p>${txt(b.assumptions)}</p></div><div><h4>${__("Exclusions")}</h4><p>${txt(b.exclusions)}</p></div></div>
          <div><h4>${__("Internal Notes")}</h4><div class="bq-rich">${b.notes ? b.notes : `<span class="fo-muted">${__("Not recorded")}</span>`}</div></div>
          <p class="fo-muted small">${__("Prepared by {0} on {1}. Last updated by {2}.", [esc(d.users.prepared_by || ""), fmtD(b.estimate_date), esc(d.users.modified_by || "")])}</p></div>`);
