  /* ---------------- actions ---------------- */
  async function mutateBoq(fn, msg) {
    try {
      const r = await frappe.call({ method: "frappe.client.get", args: { doctype: "Fit Out BOQ", name: BQ.name } });
      const doc = r.message;
      fn(doc);
      (doc.items || []).forEach((x, i) => (x.idx = i + 1));
      await frappe.call({ method: "frappe.client.save", args: { doc } });
      frappe.show_alert({ message: msg, indicator: "green" });
      loadBoq();
      return true;
    } catch (e) { return false; }
  }
  async function setBoq(values, msg) {
    try {
      await frappe.call({ method: "frappe.client.set_value", args: { doctype: "Fit Out BOQ", name: BQ.name, fieldname: values } });
      frappe.show_alert({ message: msg, indicator: "green" });
      loadBoq();
      return true;
    } catch (e) { return false; }
  }
  const SECTION_HINTS = ["Partition Works", "Ceiling Works", "Flooring", "Joinery", "Electrical", "HVAC Coordination", "Plumbing", "Fire Fighting", "Painting", "Glass & Doors", "Wall Finishes", "Signage", "Preliminaries"];
  function itemDialog(it) {
    if (!BQ.d) return;
    const b = BQ.d.boq, locked = isLocked(b);
    const secs = [...new Set((BQ.d.items || []).map((x) => x.work_section).filter(Boolean).concat(SECTION_HINTS))];
    let d;
    const upd = () => {
      if (!d) return;
      const v = d.get_values(true) || {};
      const rate = flt(v.material_rate) + flt(v.labour_rate) + flt(v.subcontract_rate) + flt(v.other_rate);
      d.fields_dict.calc.$wrapper.html(`<div class="text-muted" style="margin:-4px 0 10px">${__("Unit rate")}: <b>${num2(rate)}</b> · ${__("Amount")}: <b>${cur2(rate * flt(v.qty), bcur())}</b>${locked ? `<br><span class="text-danger">${__("This estimate is locked. Create a revision to change it.")}</span>` : ""}</div>`);
    };
    const cur = { fieldtype: "Currency", onchange: () => upd() };
    d = new frappe.ui.Dialog({
      title: it ? `${__("Item")} ${it.idx} · ${esc(it.work_section)}` : __("Add BOQ Item"),
      size: "large",
      fields: [
        { fieldname: "work_section", label: __("Work Section"), fieldtype: "Autocomplete", options: secs, reqd: 1, default: it ? it.work_section : BQ.section || "" },
        { fieldname: "uom", label: __("Unit"), fieldtype: "Link", options: "UOM", default: it ? it.uom : "" },
        { fieldtype: "Column Break" },
        { fieldname: "qty", label: __("Quantity"), fieldtype: "Float", reqd: 1, default: it ? it.qty : 1, onchange: () => upd() },
        { fieldname: "supplier", label: __("Subcontractor / Supplier"), fieldtype: "Link", options: "Supplier", default: it ? it.supplier : "" },
        { fieldtype: "Section Break" },
        { fieldname: "description", label: __("Description"), fieldtype: "Small Text", default: it ? it.description : "" },
        { fieldtype: "Section Break", label: __("Cost rates per unit") },
        Object.assign({ fieldname: "material_rate", label: __("Material") }, cur, { default: it ? it.material_rate : 0 }),
        Object.assign({ fieldname: "labour_rate", label: __("Labour") }, cur, { default: it ? it.labour_rate : 0 }),
        { fieldtype: "Column Break" },
        Object.assign({ fieldname: "subcontract_rate", label: __("Subcontractor") }, cur, { default: it ? it.subcontract_rate : 0 }),
        Object.assign({ fieldname: "other_rate", label: __("Other Direct") }, cur, { default: it ? it.other_rate : 0 }),
        { fieldtype: "Section Break" },
        { fieldname: "calc", fieldtype: "HTML" },
        { fieldname: "remarks", label: __("Remarks"), fieldtype: "Small Text", default: it ? it.remarks : "" },
      ],
      primary_action_label: locked ? undefined : it ? __("Save") : __("Add Item"),
      primary_action: locked ? undefined : async (v) => {
        const vals = { work_section: v.work_section, uom: v.uom || "", qty: v.qty, supplier: v.supplier || "", description: v.description || "", remarks: v.remarks || "",
          material_rate: v.material_rate || 0, labour_rate: v.labour_rate || 0, subcontract_rate: v.subcontract_rate || 0, other_rate: v.other_rate || 0 };
        const ok = await mutateBoq((doc) => {
          if (it) Object.assign(doc.items.find((x) => x.name === it.name) || {}, vals);
          else doc.items = (doc.items || []).concat([Object.assign({ doctype: "Fit Out BOQ Item" }, vals)]);
        }, it ? __("Item updated") : __("Item added"));
        if (ok) d.hide();
      },
    });
    d.show(); upd();
