  function createQuotation() {
    const d0 = BQ.d; if (!d0) return;
    const b = d0.boq, s = d0.summary, secs = d0.sections || [];
    if (!secs.length) return frappe.msgprint(__("Add BOQ items before raising a quotation."));
    const price = s.selling_price || s.suggested_price;
