    const d = new frappe.ui.Dialog({
      title: __("Create Quotation from {0}", [esc(b.name)]),
      fields: [
        { fieldname: "info", fieldtype: "HTML", options: `<div style="margin-bottom:10px">${__("Total")}: <b>${cur2(price, d0.currency)}</b> ${s.selling_price ? __("(proposed selling price, before tax)") : __("(suggested price — no selling price set)")}</div>` },
