      if (act === "var-upload") return xUpload("Fit Out Variation", v.name, () => loadX("var"));
      if (act === "var-approve") return varDecision(v, "Approved");
      if (act === "var-reject") return varDecision(v, "Rejected");
      if (act === "var-next") return varNext(v);
      if (act === "var-submit") return xSet("Fit Out Variation", v.name, { status: "Submitted to Client", next_action: __("Follow up on the commercial quotation."), action_due: frappe.datetime.add_days(frappe.datetime.get_today(), 7) }, __("Marked as issued to client")).then(() => loadX("var")).catch(() => {});
      if (act === "var-detmenu") return openMenu(el, [{ label: __("Open variation form"), icon: "open", run: () => goForm("Fit Out Variation", v.name) },
        { label: __("Attach document"), icon: "upload", run: () => xUpload("Fit Out Variation", v.name, () => loadX("var")) },
        { label: __("New document register entry"), icon: "filetext", run: () => frappe.new_doc("Fit Out Document", { project: v.project, variation: v.name, category: "Correspondence", document_title: v.title }) }]);
      if (act === "var-listmenu") return openMenu(el, [{ label: __("Open variation list"), icon: "list", run: () => goList("Fit Out Variation", st.project ? { project: st.project } : {}) },
        { label: __("Approval rules"), icon: "gear", run: () => showX("wf") }, { label: __("Refresh"), icon: "refresh", run: () => loadX("var") }]);
      if (act === "var-allnext") {
