      if (VAR_OPEN.includes(r.status)) items.push("-", { label: __("Record client approval"), icon: "circlecheck", run: () => varDecision(r, "Approved") }, { label: __("Record rejection"), icon: "xcircle", run: () => varDecision(r, "Rejected") });
