      detailDialog(__("Variations"), list.map((r) => li("Fit Out Variation", r.name, `<b>${esc(r.title)}</b> · ${esc(r.name)}`, `${badge(r.status)}<br>${xm(r.value, xcur(st.d))}`)).join(""), __("None."));
