  };

  /* =================== ACCOUNTING =================== */
  XR.acct = function (d, st) {
    const f = d.fin, cur = xcur(d);
    const btns = `<button class="fo-btn ghost" data-xa="acct-ledger">${ic("list", "sm")}${__("Cost Ledger")}</button><button class="fo-btn" data-xa="acct-forecast">${ic("trend", "sm")}${__("Review Forecast")}</button>`;
    if (!f) return `${xTop("acct", d, btns)}<div class="es-body"><div class="fo-empty"><b>${__("No projects in scope")}</b></div></div>`;
    const over = f.variance > 0.5;
    const kp = xKpis([
      { key: "contract", label: __("Approved Contract Value"), value: xm(f.current_contract, cur), money: 1, sub: __("Original contract plus approved variations"), icon: "filetext", c: "blue" },
      { key: "budget", label: __("Revised Approved Cost Budget"), value: xm(f.revised_budget, cur), money: 1, sub: __("Original budget plus approved variation costs"), icon: "clipboard", c: "purple" },
      { key: "actual", label: __("Actual Cost Incurred"), value: xm(f.actual, cur), money: 1, sub: f.gl === 0 && d.head ? __("From project costing (no tagged postings yet)") : __("Costs recorded to date"), icon: "database", c: "sky" },
      { key: "forecast", label: __("Forecast Final Cost"), value: xm(f.forecast, cur), money: 1, sub: __("Expected total cost at completion"), icon: "barchart", c: "orange" },
      { key: "profit", label: __("Forecast Gross Profit"), value: xm(f.profit, cur), money: 1, vcls: f.profit >= 0 ? "pos" : "neg", sub: __("Projected profit (before tax)"), icon: "pie", c: "green" },
    ], "xv-k5");
    const bc = `<section class="pj-sec es-card xv-bc">${xSec(__("Budget Control"))}
      <div class="xv-mt"><div class="xv-mth"><span>${__("Description")}</span><span>${__("Amount")} (${esc(cur)})</span></div>
      ${[[__("Original Approved Contract Value"), xnum(f.original_contract)], [__("Original Estimated Project Cost"), xnum(f.original_cost)], [__("Original Estimated Gross Profit"), xnum(f.original_profit)],
        [__("Original Estimated Gross Margin"), xpct(f.original_margin)], [__("Approved Variation Selling Value"), xnum(f.approved_var_sell)], [__("Approved Variation Cost Impact"), xnum(f.approved_var_cost)]]
        .map((r) => `<div class="xv-mr"><span>${r[0]}</span><b>${r[1]}</b></div>`).join("")}
      <div class="xv-mr hl blue"><span>${__("Current Approved Contract Value")}</span><b>${xnum(f.current_contract)}</b></div>
      <div class="xv-mr hl purple"><span>${__("Revised Approved Cost Budget")}</span><b>${xnum(f.revised_budget)}</b></div></div></section>`;
    const fc = Math.max(1, f.forecast);
    const bar = (label, v, color, hl) => `<div class="xv-ctc ${hl ? "hl" : ""}"><span>${label}</span><b>${xm(v, cur)}</b><div class="fo-bar"><i data-w="${Math.min(100, Math.round((v / fc) * 100))}" style="background:${color}"></i></div><em>${Math.round((v / fc) * 100)}%</em></div>`;
    const ctc = `<section class="pj-sec es-card xv-ctcc">${xSec(__("Cost-to-Complete Forecast"))}
      ${bar(__("Actual Cost Incurred"), f.actual, "var(--blue)")}${bar(__("Outstanding Committed Cost"), f.committed, "var(--purple)")}${bar(__("Forecast Uncommitted Remaining Cost"), f.uncommitted, "#60A5FA")}
      ${bar(__("Forecast Final Project Cost"), f.forecast, "var(--navy)", 1)}
      <div class="xv-rem"><div><b>${__("Remaining Forecast Expenditure")}</b><span>${__("Committed + Uncommitted Remaining Cost")}</span></div><b>${xm(f.committed + f.uncommitted, cur)}</b></div></section>`;
    const vcard = `<section class="pj-sec es-card xv-varc">${xSec(__("Forecast Cost Variance"))}
      <div class="xv-vtag ${over ? "bad" : "ok"}"><span>${ic(over ? "alert" : "circlecheck")}</span><b>${over ? __("COST REVIEW REQUIRED") : __("WITHIN APPROVED BUDGET")}</b></div>
      ${xRow(__("Revised Approved Cost Budget"), xm(f.revised_budget, cur))}${xRow(__("Forecast Final Project Cost"), xm(f.forecast, cur))}
      ${xRow(over ? __("Forecast Cost Overrun") : __("Forecast Cost Saving"), xm(Math.abs(f.variance), cur), over ? "hl red" : "hl green")}
      <p class="xv-note">${over ? __("Forecast expenditure is {0} above the revised approved budget. Review outstanding commitments and remaining work-package costs.", [xm(f.variance, cur)]) : __("Actual, committed and remaining costs are forecast within the revised approved budget.")}</p></section>`;
    const prof = `<section class="pj-sec es-card xv-prof">${xSec(__("Projected Project Profitability"))}
      ${xRow(__("Current Approved Contract Value"), xm(f.current_contract, cur))}${xRow(__("Forecast Final Project Cost"), xm(f.forecast, cur))}
      ${xRow(__("Forecast Gross Profit"), xm(f.profit, cur), f.profit >= 0 ? "hl green xv-big" : "hl red xv-big")}
      <div class="bq-sr bq-margin ${f.margin == null ? "" : f.margin < 0 ? "neg" : f.target_margin && f.margin < f.target_margin ? "warn" : ""}"><span>${__("Forecast Gross Margin")}</span><b>${xpct(f.margin)}</b></div>
      ${f.target_margin ? `<div class="xv-note">${__("Target margin")}: ${xpct(f.target_margin)}</div>` : ""}</section>`;
    const lines = f.lines || [];
    const colors = ["var(--blue)", "var(--purple)", "#3B82F6", "#60A5FA"];
    const brk = `<section class="pj-sec es-card xv-brk">${xSec(`${__("Project Cost Breakdown")} <small class="xv-sm">(${__("Forecast Final Cost")})</small>`, "barchart")}
      <div class="pj-tbl-wrap"><table class="pj-tbl es-tbl xv-tbl xv-brkt"><thead><tr><th>${__("Cost Category")}</th><th class="r">${__("Amount")} (${esc(cur)})</th><th class="r">% ${__("of Total")}</th><th></th></tr></thead><tbody>
      ${lines.map((l, i) => { const p = f.forecast ? (l.forecast * 100) / f.forecast : 0; return `<tr data-xrow="line" data-i="${i}" title="${esc(__("Budget"))} ${xm(l.budget, cur)} · ${esc(__("Actual"))} ${xm(l.actual, cur)} · ${esc(__("Committed"))} ${xm(l.committed, cur)}${l.override ? " · " + esc(__("Forecast reviewed")) : ""}"><td>${esc(__(l.category))}${l.override ? ` <span class="xv-dot" title="${esc(__("Forecast reviewed manually"))}"></span>` : ""}</td><td class="r">${xnum(l.forecast)}</td><td class="r">${Math.round(p)}%</td><td><div class="fo-bar xv-wbar"><i data-w="${Math.round(p)}" style="background:${colors[i % 4]}"></i></div></td></tr>`; }).join("")}
      </tbody><tfoot><tr><td>${__("Total Forecast Project Cost")}</td><td class="r">${xnum(f.forecast)}</td><td class="r">100%</td><td><div class="fo-bar xv-wbar"><i data-w="100" style="background:var(--navy)"></i></div></td></tr></tfoot></table></div></section>`;
    const mx = Math.max(f.revised_budget, f.forecast, 1);
    const step = Math.pow(10, Math.floor(Math.log10(mx))) * (mx / Math.pow(10, Math.floor(Math.log10(mx))) > 5 ? 2 : 1);
    const top = Math.ceil(mx / step) * step;
    const ticks = []; for (let t = 0; t <= top + 0.1; t += step) ticks.push(t);
    const H = 150, y = (v) => 10 + H - (v / top) * H;
    const chart = `<svg viewBox="0 0 300 200" class="xv-chart" role="img" aria-label="${esc(__("Project Cost Position"))}">
      ${ticks.map((t) => `<line x1="52" x2="290" y1="${y(t)}" y2="${y(t)}" stroke="#EEF1F7"/><text x="46" y="${y(t) + 4}" text-anchor="end">${xnum(t)}</text>`).join("")}
      <rect x="90" y="${y(f.revised_budget)}" width="56" height="${Math.max(1, H + 10 - y(f.revised_budget))}" rx="4" fill="#2563EB"><title>${esc(xm(f.revised_budget, cur))}</title></rect>
      <rect x="196" y="${y(f.forecast)}" width="56" height="${Math.max(1, H + 10 - y(f.forecast))}" rx="4" fill="#7C3AED"><title>${esc(xm(f.forecast, cur))}</title></rect>
      <text x="118" y="${y(f.revised_budget) - 6}" text-anchor="middle" class="v">${esc(xm(f.revised_budget, cur))}</text>
      <text x="224" y="${y(f.forecast) - 6}" text-anchor="middle" class="v">${esc(xm(f.forecast, cur))}</text>
      <text x="118" y="178" text-anchor="middle" class="l">${esc(__("Revised Approved"))}</text><text x="118" y="191" text-anchor="middle" class="l">${esc(__("Cost Budget"))}</text>
      <text x="224" y="178" text-anchor="middle" class="l">${esc(__("Forecast Final Cost"))}</text></svg>`;
    const pos = `<section class="pj-sec es-card xv-pos">${xSec(__("Project Cost Position"), "barchart")}
      <div class="xv-posg">${chart}<div class="xv-vbox ${over ? "bad" : "ok"}"><span>${__("Variance")}</span><b>${xm(Math.abs(f.variance), cur)}</b><small>(${over ? __("Unfavourable") : __("Favourable")})</small></div></div></section>`;
    const pr = d.priorities || [];
    const PI = { variance: ["alert", "k-delivery"], category: ["alert", "k-inspect"], commit: ["clipboard", "k-milestone"], variation: ["filetext", "k-variation"], margin: ["trend", "k-inspect"] };
    const fp = `<section class="pj-sec es-card xv-fp">${xSec(__("Financial Priorities"), "list", pr.length > 3 ? __("View All") : "", "acct-allpri")}
      ${pr.length ? `<div class="xv-fpl">${pr.slice(0, 3).map((p, i) => `<div class="xv-fpi" data-xpri="${i}"><span class="pj-ui-ico ${(PI[p.kind] || [])[1] || ""}">${ic((PI[p.kind] || ["alert"])[0])}</span>
        <div><b>${esc(__(p.title))}</b><span>${esc(p.issue)}</span></div><p><small>${__("Next Action")}:</small> ${esc(p.next)}</p></div>`).join("")}</div>`
        : `<div class="pj-empty pc-ok">${ic("checksq", "sm")} ${__("Costs and margin are on plan.")}</div>`}</section>`;
    const prj = d.projects || [];
    const ptab = !d.head && prj.length ? `<section class="pj-sec es-card">${xSec(__("Project Financial Summary"), "building")}
      ${xTable([{ l: __("Project"), f: (r) => `<b>${esc(r.name)}</b> ${xell(r.project_name, "", 220)}` }, { l: __("Contract"), r: 1, f: (r) => xnum(r.contract) }, { l: __("Revised Budget"), r: 1, f: (r) => xnum(r.budget) },
        { l: __("Actual"), r: 1, f: (r) => xnum(r.actual) }, { l: __("Committed"), r: 1, f: (r) => xnum(r.committed) }, { l: __("Forecast Final"), r: 1, f: (r) => xnum(r.forecast) },
        { l: __("Variance"), r: 1, f: (r) => `<span class="${r.variance > 0.5 ? "xv-neg" : "xv-pos"}">${xnum(r.variance)}</span>` }, { l: __("Forecast GP"), r: 1, f: (r) => xnum(r.profit) }, { l: __("Margin"), r: 1, f: (r) => xpct(r.margin) }], prj, { kind: "proj" })}</section>` : "";
    return `${xTop("acct", d, btns)}<div class="es-body">${xHero(d.head)}${kp}
      <div class="es-row xv-r4">${bc}${ctc}${vcard}${prof}</div>
      <div class="es-row xv-r3">${brk}${pos}${fp}</div>${ptab}</div>`;
  };
  function forecastDialog(st) {
    const d = st.d, f = d && d.fin; if (!f) return;
    const pn = xRequireProject("acct", __("review its forecast")); if (!pn) return;
    const cur = xcur(d), ov = f.overrides || {};
    const fields = [{ fieldtype: "HTML", options: `<div class="text-muted" style="margin-bottom:6px">${__("Enter the cost still expected to complete each category (beyond actual and committed costs). Leave a value empty to keep the automatic budget-based forecast.")}</div>` }];
    (f.lines || []).forEach((l, i) => {
      if (i === 2) fields.push({ fieldtype: "Column Break" });
      fields.push({ fieldname: "c" + i, fieldtype: "Currency", label: __(l.category), default: ov[l.category] ? ov[l.category].value : null,
        description: `${__("Budget")} ${xm(l.budget, cur)} · ${__("Actual")} ${xm(l.actual, cur)} · ${__("Committed")} ${xm(l.committed, cur)} · ${__("Auto")} ${xm(Math.max(0, l.budget - l.actual - l.committed), cur)}` });
    });
    fields.push({ fieldtype: "Section Break" }, { fieldname: "note", fieldtype: "Data", label: __("Basis / note"), default: Object.values(ov)[0] ? Object.values(ov)[0].note : "" });
    const dlg = new frappe.ui.Dialog({
      title: `${__("Cost-to-Complete Forecast")} · ${esc(pn)}`, size: "large", fields,
      primary_action_label: __("Save Forecast"),
      async primary_action(vals) {
        try {
          const doc = await xGet("Project", pn);
          doc.fo_ctc = (f.lines || []).map((l, i) => vals["c" + i] === null || vals["c" + i] === undefined || vals["c" + i] === "" ? null
            : { doctype: "Fit Out Cost Forecast", category: l.category, forecast_to_complete: flt(vals["c" + i]), note: vals.note || "", updated_on: frappe.datetime.get_today() }).filter(Boolean);
          await xSave(doc, __("Forecast saved"));
          dlg.hide(); loadX("acct");
        } catch (e) {}
      },
      secondary_action_label: __("Clear manual forecast"),
      async secondary_action() { try { const doc = await xGet("Project", pn); doc.fo_ctc = []; await xSave(doc, __("Using the automatic forecast")); dlg.hide(); loadX("acct"); } catch (e) {} },
    });
    dlg.show();
  }
  XH.acct = {
    act(act, el, st) {
      const d = st.d || {};
