    kpi(key, st, dots) {
      const d = st.d || {}, cur = xcur(d), f = d.fin || {};
      if (key === "actual" || key === "forecast") return dots ? openMenu(dots, [{ label: __("Cost ledger"), icon: "list", run: () => XH.acct.act("acct-ledger", null, st) }, { label: __("Review forecast"), icon: "trend", run: () => forecastDialog(st) }]) : XH.acct.act("acct-ledger", null, st);
      if (key === "contract") return showX("var", st.project || undefined);
      if (key === "budget") return d.head && d.head.baseline_boq ? openBoq(d.head.baseline_boq) : showBoqs();
      if (key === "profit") detailDialog(__("Forecast Gross Profit"), `<div class="list-group-item">${__("Current approved contract")}: <b>${xm(f.current_contract, cur)}</b><br>${__("Forecast final cost")}: <b>${xm(f.forecast, cur)}</b><br>${__("Forecast gross profit")}: <b>${xm(f.profit, cur)}</b> (${xpct(f.margin)})</div>`, "");
