      { key: "billed", label: __("Billed to Date"), value: xm(k.billed, cur), money: 1, sub: k.billed_pct != null ? `${k.billed_pct}% ${__("of contract")}` : __("No contract value"), icon: "receipt", c: "purple" },
      { key: "collected", label: __("Collected"), value: xm(k.collected, cur), money: 1, sub: __("Payments received"), icon: "coins", c: "green" },
