    ]);
    const all = !d.head;
    const reg = `<section class="pj-sec es-card">${xSec(__("Invoice Register"), "receipt", (d.invoices || []).length ? __("View All") : "", "inv-all")}
      ${xTable([{ l: __("Invoice"), f: (r) => `<span class="es-id">${esc(r.name)}</span>${r.is_return ? ` <small class="fo-muted">${__("Credit")}</small>` : ""}` },
        ...(all ? [{ l: __("Project"), f: (r) => xell(r.project, "", 110) }] : []), { l: __("Client"), f: (r) => xell(r.customer, "", 150) },
        { l: __("Date"), f: (r) => xdate(r.date) }, { l: __("Due"), f: (r) => `<span class="${r.status === "Overdue" ? "es-late" : ""}">${xdate(r.due)}</span>` },
        { l: `${__("Amount")} (${esc(cur)})`, r: 1, f: (r) => xnum(r.total) }, { l: __("Outstanding"), r: 1, f: (r) => (r.outstanding ? xnum(r.outstanding) : `<span class="fo-muted">—</span>`) },
        { l: __("Status"), f: (r) => badge(r.status) }], d.invoices || [], { kind: "inv", limit: 10, moreAct: "inv-all", empty: `${__("No invoices yet.")} <a data-xa="inv-new">${__("Raise the first invoice")}</a>` })}</section>`;
    const prj = d.projects || [];
    const bp = `<section class="pj-sec es-card xv-bp">${xSec(__("Billing Progress by Project"), "trend")}
      ${prj.length ? prj.map((p, i) => `<div class="xv-bpi" data-xrow="bp" data-i="${i}"><div class="xv-bph"><b>${esc(p.name)}</b>${xell(p.project_name, "", 200)}<span>${xm(p.billed, cur)} / ${xm(p.contract, cur)}</span></div>
