        <div class="xv-bpb"><small>${__("Billed")}</small><div class="fo-bar"><i data-w="${Math.min(100, p.billed_pct || 0)}" style="background:var(--purple)"></i></div><em>${p.billed_pct != null ? Math.round(p.billed_pct) + "%" : "—"}</em></div>
        ${p.unbilled > p.contract * 0.05 && p.contract ? `<div class="xv-bpn">${__("About {0} of progress not yet billed", [xm(p.unbilled, cur)])}</div>` : p.overdue ? `<div class="xv-bpn bad">${xm(p.overdue, cur)} ${__("overdue")}</div>` : ""}</div>`).join("")
