.xv-pki .fo-kpi-ico { width: 46px; height: 46px; } .xv-pki .fo-kpi-ico svg.i { width: 22px; height: 22px; }
.xv-pki div { display: flex; flex-direction: column; min-width: 0; }
.xv-pki small { font-size: 12px; font-weight: 700; color: var(--navy); text-transform: uppercase; letter-spacing: .2px; line-height: 1.2; }
.xv-pki b { font-size: 28px; font-weight: 800; color: var(--navy); line-height: 1.15; }
.xv-pki em { font-style: normal; font-size: 12px; color: var(--muted); line-height: 1.3; }
.xv-hsm { min-width: 0; font-size: 12px; padding: 4px 9px; }
.xv-ctlg { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.xv-ctli { position: relative; display: flex; gap: 10px; padding: 12px; border: 1px solid var(--line); border-radius: 12px; cursor: pointer; min-width: 0; }
.xv-ctli:hover { border-color: #C9D6F2; background: #FAFCFF; }
.xv-cti { width: 38px; height: 38px; border-radius: 10px; display: grid; place-items: center; background: var(--blue-50); color: var(--blue); flex: none; }
.xv-ctli div { min-width: 0; padding-right: 18px; }
.xv-ctli b { font-size: 13px; color: var(--navy); display: block; } .xv-ctli p { margin: 2px 0 4px; font-size: 12px; color: #46527A; line-height: 1.35; } .xv-ctli small { font-size: 11.5px; color: var(--muted); }
.xv-cts { position: absolute; top: 10px; right: 10px; width: 22px; height: 22px; border-radius: 50%; display: grid; place-items: center; color: #fff; }
.xv-cts.ok { background: #16A34A; } .xv-cts.warn { background: var(--orange); } .xv-cts.info { background: var(--blue); }
.xv-cts svg.i { width: 13px; height: 13px; stroke-width: 2.6; }
.xv-snapg { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.xv-sni { display: flex; gap: 10px; align-items: center; padding: 12px; border: 1px solid var(--line); border-radius: 12px; cursor: pointer; min-width: 0; }
.xv-sni:hover { background: #FAFCFF; }
.xv-sni .fo-kpi-ico { width: 40px; height: 40px; } .xv-sni .fo-kpi-ico svg.i { width: 20px; height: 20px; }
.xv-sni div { display: flex; flex-direction: column; min-width: 0; }
.xv-sni small { font-size: 12px; color: #46527A; } .xv-sni b { font-size: 19px; font-weight: 800; color: var(--navy); white-space: nowrap; }
.xv-mpi { display: flex; gap: 8px; align-items: center; } .xv-mpi .pj-ui-ico { width: 30px; height: 30px; flex: none; }
.xv-mpi div { display: flex; flex-direction: column; } .xv-mpi b { font-size: 12.5px; color: var(--navy); } .xv-mpi small { font-size: 11.5px; color: var(--muted); }
.xv-mp td { vertical-align: middle; }
.xv-libg { display: flex; flex-wrap: wrap; gap: 8px; }
.xv-libi { display: inline-flex; align-items: center; gap: 7px; padding: 8px 12px; border: 1px solid var(--line); border-radius: 10px; font-size: 13px; font-weight: 600; color: var(--navy); background: #fff; }
.xv-libi:hover { border-color: #C9D6F2; color: var(--blue); }
.xv-libi span { display: flex; color: var(--blue); }

/* responsive */
@container fo (max-width: 1500px) {
  .xv .xv-k5 .fo-kpi-val.m { font-size: 18px; }
  .xv-r4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .xv-r-var2 { grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr); } .xv-r-var2 .xv-hist { grid-column: 1 / -1; }
  .xv-r-doc2 { grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); } .xv-r-doc2 .xv-cp { grid-column: 1 / -1; }
  .xv-r-wf2 { grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr); } .xv-r-wf2 .xv-bay { grid-column: 1 / -1; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px 14px; } .xv-r-wf2 .xv-bay .es-h { grid-column: 1 / -1; }
  .xv-r-rep2 { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); } .xv-r-rep2 .xv-mp { grid-column: 1 / -1; }
  .xv-phead { grid-template-columns: 170px minmax(0, 1fr); } .xv-pk { grid-column: 1 / -1; }
}
@container fo (max-width: 1300px) {
  .xv .xv-k5 { grid-template-columns: repeat(6, minmax(0, 1fr)); }
  .xv .xv-k5 > * { grid-column: span 2 !important; } .xv .xv-k5 > :nth-child(4), .xv .xv-k5 > :nth-child(5) { grid-column: span 3 !important; }
  .xv-r-var1, .xv-r-doc1, .xv-r-wf1, .xv-r-rep1 { grid-template-columns: minmax(0, 1fr); }
  .xv-r3 { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); } .xv-r3 .xv-fp { grid-column: 1 / -1; }
  .xv-infos { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@container fo (max-width: 1000px) {
  .xv .xv-kpis.pc-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .xv-r4, .xv-r3, .xv-r-var2, .xv-r-doc2, .xv-r-wf2, .xv-r-rep2 { grid-template-columns: minmax(0, 1fr); }
  .xv-r-wf2 .xv-bay { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .xv-det-g, .xv-apg { grid-template-columns: minmax(0, 1fr); } .xv-aset { border-left: 0; padding-left: 0; border-top: 1px solid var(--line); padding-top: 10px; }
  .xv-fg { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .xv-pk { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .xv-vfoot { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@container fo (max-width: 640px) {
  .xv .xv-kpis.pc-kpis, .xv .xv-k5 { grid-template-columns: minmax(0, 1fr); } .xv .xv-k5 > * { grid-column: auto !important; }
  .xv-infos, .xv-bfg, .xv-fg, .xv-tiles, .xv-ctlg, .xv-snapg, .xv-pk { grid-template-columns: minmax(0, 1fr); }
  .xv-phead { grid-template-columns: minmax(0, 1fr); } .xv-pimg { height: 140px; }
  .xv-hsg, .xv-posg { grid-template-columns: minmax(0, 1fr); justify-items: center; }
  .xv-top .fo-controls { width: 100%; } .xv-top .fo-pill { flex: 1; min-width: 0; } .xv-top .fo-pill select { max-width: 100%; }
  .xv-apf { flex-wrap: wrap; } .xv-apa { display: none; } .xv-aps { flex: 1 1 40%; }
  .xv-vfoot { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .xv-hi, .xv-fpi { grid-template-columns: 34px minmax(0, 1fr); } .xv-hin, .xv-fpi p { grid-column: 2; }
}
